// ── helpers ──────────────────────────────────────────────────────────────────

/**
 * The Rust `Serialize` impl writes every absent field as an explicit `null`;
 * the TypeScript leaves it off entirely, because `exactOptionalPropertyTypes`
 * makes "absent" and "present and undefined" different types. Normalize to the
 * Rust shape so a field that should be gone cannot pass by being `undefined`.
 */
function toWire(model: ResolvedModel): Record<string, unknown> {
  const keepalive = model.cacheKeepalive;
  return {
    name: model.name,
    qualified_name: model.qualifiedName,
    category: model.category,
    provider_key: model.providerKey,
    sdk: model.sdk,
    model_id: model.modelId,
    api_key_env: model.apiKeyEnv ?? null,
    base_url: model.baseUrl ?? null,
    max_context_tokens: model.maxContextTokens ?? null,
    max_output_tokens: model.maxOutputTokens ?? null,
    temperature: model.temperature ?? null,
    top_p: model.topP ?? null,
    reasoning_effort: model.reasoningEffort ?? null,
    budget_tokens: model.budgetTokens ?? null,
    cache_ttl: model.cacheTtl ?? null,
    cache_keepalive: keepalive === undefined ? null : keepaliveToString(keepalive),
    openrouter_provider: model.openrouterProvider ?? null,
    gemini_generation: model.geminiGeneration ?? null,
    zai_clear_thinking: model.zaiClearThinking ?? null,
    zai_subscription: model.zaiSubscription ?? null,
    replay_prior_thinking: model.replayPriorThinking ?? null,
    max_tool_iterations: model.maxToolIterations ?? null,
  };
}

/** The same normalization for a bare field bag (`ModelConfigFields`). */
function fieldsToWire(fields: ModelConfigFields): Record<string, unknown> {
  const keepalive = fields.cacheKeepalive;
  return {
    sdk: fields.sdk ?? null,
    api_key_env: fields.apiKeyEnv ?? null,
    base_url: fields.baseUrl ?? null,
    max_context_tokens: fields.maxContextTokens ?? null,
    max_output_tokens: fields.maxOutputTokens ?? null,
    temperature: fields.temperature ?? null,
    top_p: fields.topP ?? null,
    reasoning_effort: fields.reasoningEffort ?? null,
    budget_tokens: fields.budgetTokens ?? null,
    cache_ttl: fields.cacheTtl ?? null,
    cache_keepalive: keepalive === undefined ? null : keepaliveToString(keepalive),
    openrouter_provider: fields.openrouterProvider ?? null,
    gemini_generation: fields.geminiGeneration ?? null,
    zai_clear_thinking: fields.zaiClearThinking ?? null,
    zai_subscription: fields.zaiSubscription ?? null,
  };
}

function parseToml(text: string): Record<string, unknown> | undefined {
  if (text.trim() === "") return undefined;
  return Bun.TOML.parse(text) as Record<string, unknown>;
}

/** A registry view backed by a parsed `[providers]` table, standing in until
 *  `providers.ts` lands. Only the two transport fields and `defaults` matter
 *  to the cascade. */
function registryFromToml(text: string): ProviderRegistryView | undefined {
  const table = parseToml(text);
  if (table === undefined) return undefined;
  const entries = new Map<string, ProviderRegistryEntry>();
  for (const [name, raw] of Object.entries(table)) {
    const body = raw as Record<string, unknown>;
    const defaultsTable = (body["defaults"] ?? {}) as Record<string, unknown>;
    const defaults: ModelConfigFields = {};
    if (typeof defaultsTable["max_output_tokens"] === "number") {
      defaults.maxOutputTokens = defaultsTable["max_output_tokens"];
    }
    if (typeof defaultsTable["max_context_tokens"] === "number") {
      defaults.maxContextTokens = defaultsTable["max_context_tokens"];
    }
    if (typeof defaultsTable["temperature"] === "number") {
      defaults.temperature = defaultsTable["temperature"];
    }
    if (typeof defaultsTable["cache_ttl"] === "string") {
      defaults.cacheTtl = defaultsTable["cache_ttl"];
    }
    const entry: ProviderRegistryEntry = { defaults };
    if (typeof body["sdk"] === "string") entry.sdk = body["sdk"] as Sdk;
    if (typeof body["base_url"] === "string") entry.baseUrl = body["base_url"];
    entries.set(name, entry);
  }
  return { get: (name) => entries.get(name) };
}

/**
 * The daemon-authored part of a catalog error.
 *
 * `CatalogError::ParseEntry` embeds a `toml::de::Error`, which appends its own
 * presentation — a trailing newline and, when the crate happens to have kept
 * the key in scope, an `in \`<key>\`` line. That decoration is the TOML
 * crate's, is inconsistent between otherwise identical failures (`model_id`
 * gets the key annotation; a flattened field does not), and is not something
 * a port should reproduce. Everything before the first newline is Shore's own
 * message and is pinned exactly.
 */
function firstLine(message: string): string {
  return message.split("\n")[0] as string;
}

function catchCatalogError(fn: () => unknown): CatalogError {
  try {
    fn();
  } catch (e) {
    if (e instanceof CatalogError) return e;
    throw e;
  }
  throw new Error("expected a CatalogError");
}

describe("the fixture is real", () => {
  test("it was frozen, and says so", () => {
    const header = fixture._header.join(" ");
    expect(header).toContain("nothing regenerates this file");
  });

  // Every other fixture in this series was generated from the 9023b46d
  // worktree, and this one was not. Asserting the provenance it actually has
  // is what stops a later edit from copying a neighbour's header onto it.
  test("it names `main` as its source, not the worktree", () => {
    expect(fixture._header.join(" ")).toContain("GENERATED from `main`");
  });
});

// ── duration ─────────────────────────────────────────────────────────────────

describe("ConfigDuration.parse", () => {
  for (const row of fx.duration_parse) {
    test(`parses ${JSON.stringify(row.raw)}`, () => {
      const result = ConfigDuration.parse(row.raw);
      if (row.err !== undefined) {
        expect(result).toEqual({ err: row.err });
      } else {
        expect("ok" in result).toBe(true);
        if ("ok" in result) {
          expect(result.ok.asMillisExact().toString()).toBe(row.millis as string);
        }
      }
    });
  }

  test("rejects the BOM that JavaScript's own trim would have swallowed", () => {
    // `String.prototype.trim` strips U+FEFF; Rust's `str::trim` does not, so
    // the BOM stays in the string and makes the whole thing an invalid suffix.
    expect(ConfigDuration.parse("\ufeff30s")).toEqual({
      err: "invalid duration suffix: \ufeff30s",
    });
    expect("\ufeff30s".trim()).toBe("30s");
  });

  test("accepts the NEL that JavaScript's own trim would have kept", () => {
    // The mirror image: U+0085 has the Unicode White_Space property, so Rust
    // trims it, but it is neither a JavaScript WhiteSpace nor a LineTerminator.
    const parsed = ConfigDuration.parse("\u008530s");
    expect(parsed).toHaveProperty("ok");
    expect("\u008530s".trim()).toBe("\u008530s");
  });
});

describe("ConfigDuration display and accessors", () => {
  for (const row of fx.duration_display) {
    test(`renders ${row.millis} as ${row.display}`, () => {
      const d = ConfigDuration.fromMillis(BigInt(row.millis));
      expect(d.toString()).toBe(row.display);
      expect(d.asSecs().toString()).toBe(row.secs);
      expect(d.toJSON()).toBe(row.json);
    });
  }

  test("every rendered form parses back to the same milliseconds", () => {
    for (const row of fx.duration_display) {
      const reparsed = ConfigDuration.parse(row.display);
      expect(reparsed).toHaveProperty("ok");
      if ("ok" in reparsed) {
        expect(reparsed.ok.asMillisExact().toString()).toBe(row.millis);
      }
    }
  });
});

describe("ConfigDuration.fromSecs", () => {
  for (const row of fx.duration_from_secs) {
    test(`${row.secs}s saturates to ${row.millis}ms`, () => {
      expect(ConfigDuration.fromSecs(BigInt(row.secs)).asMillisExact().toString()).toBe(row.millis);
    });
  }
});

// ── cache keepalive ──────────────────────────────────────────────────────────

describe("parseCacheKeepalive", () => {
  for (const row of fx.keepalive_parse) {
    test(`parses ${JSON.stringify(row.raw)}`, () => {
      const result = parseCacheKeepalive(row.raw);
      if (row.err !== undefined) {
        expect(result).toEqual({ err: row.err });
        return;
      }
      expect(result).toHaveProperty("ok");
      if (!("ok" in result)) return;
      expect(keepaliveToString(result.ok)).toBe(row.display as string);
      const interval = keepaliveIntervalMs(result.ok);
      const expected = row.interval_millis;
      expect(interval === undefined ? null : String(interval)).toEqual(expected ?? null);
    });
  }

  test("the off spellings fold with ASCII case only", () => {
    // Rust uses `to_ascii_lowercase`. A Kelvin sign lowercases to `k` under
    // full Unicode folding but not under ASCII folding, so it must stay an
    // error rather than becoming an unrecognised-but-lowercased spelling.
    expect(parseCacheKeepalive("OFF")).toEqual({ ok: { kind: "off" } });
    expect("\u212a".toLowerCase()).toBe("k");
    expect(parseCacheKeepalive("\u212a")).toHaveProperty("err");
  });

  test("a zero interval is rejected rather than spinning a ping loop", () => {
    expect(parseCacheKeepalive("0s")).toEqual({
      err: 'cache_keepalive interval must be > 0; use "off" to disable',
    });
    // `"0"` is an *off* spelling, not a zero duration — checked first.
    expect(parseCacheKeepalive("0")).toEqual({ ok: { kind: "off" } });
  });
});

